parameters.jsCode:
const stories = $('Fetch Top Stories (24h)').all();
const topics = $('Fetch Top Topics').all();
const stats = $('Fetch Sentiment Stats').first().json;

// Format stories for Claude
const storyList = stories.slice(0, 10).map((s, i) => 
  `${i + 1}. [${s.json.source}] ${s.json.title} (sentiment: ${s.json.sentiment}, score: ${s.json.sentiment_score})`
).join('\n');

// Format topics
const topicList = topics.slice(0, 8).map(t => 
  `${t.json.topic}: ${t.json.count} mentions`
).join(', ');

return [{
  json: {
    stories: storyList,
    topics: topicList,
    stats: {
      total: stats.total,
      positive: stats.positive,
      negative: stats.negative,
      neutral: stats.neutral,
      avgSentiment: parseFloat(stats.avg_sentiment).toFixed(2)
    },
    date: new Date().toISOString().split('T')[0]
  }
}];

